"""Independent dimensional preflight, deliberately never injected into dynamics."""
import numpy as np
from .common import *
def main():
 rho=1000.;mu=.001;g=9.81;r=R;volume=4*np.pi*r**3/3;Fb=rho*volume*g;zeta=6*np.pi*mu*r;ub=Fb/zeta
 out=dict(radius_m=r,assumptions={'liquid_density_kg_m3':rho,'viscosity_Pa_s':mu,'gas_shell_mass':'Neglected only for upper-limit buoyancy force estimate','surface':'Immobilized spherical interface consistent with existing Stokes drag; no claim of shell calibration','near_wall':'Unbounded velocity estimate cannot be used at wall','gravity_direction':'Not measured; +Z used only for illustrative displacement scale'},buoyancy_force_N=Fb,unbounded_immobilized_buoyancy_speed_m_s=ub,clean_mobile_interface_speed_m_s=1.5*ub,clean_interface_scope='Hadamard-Rybczynski limiting comparison, not current shelled bubble',time_s=[.05,.15,.25,1.],displacement_m=(np.array([.05,.15,.25,1.])*ub).tolist(),center_to_top_time_s=(.0008-r)/ub,boundary_layer_m={str(f):float(np.sqrt(2*mu/rho/(2*np.pi*f))) for f in [2400000,2500000,2600000]},streaming='NOT_MODELED',buoyancy='NOT_MODELED',polydispersity='NOT_MODELED; new radius/shell responses required',tool_decision='No installation: DOLFINx Stokes solver is available as mature option but physical first-order field, wall motion/slip, attenuation and validation benchmark are not yet specified.',next_benchmarks=['Measure phase/amplitude and cavity pressure first','Independent second-order Stokes with verified wall slip or resolved boundary layer; benchmark Bach-Bruus cavity before particle coupling','Measure rotation with tracer PIV and compare frequency/power scaling','Separate acoustic-OFF buoyancy and near-wall mobility benchmark','Build APECSS tables per radius/shell/frequency, never reuse 1.78 um response for new radii'],references=[{'url':'https://arxiv.org/abs/1804.05802','title':'Bach & Bruus (2018), pressure acoustics with boundary layers and streaming','relevance':'Validated wall-slip formulation; cavity geometry and wall motion matter.'},{'url':'https://arxiv.org/abs/1905.09132','title':'Bach & Bruus (2019), bulk-driven streaming at resonance','relevance':'Overlapping cavity modes can support rotating energy flux and streaming; not evidence that this uncalibrated device does.'},{'url':'https://pmc.ncbi.nlm.nih.gov/articles/PMC4814581/','title':'Ahmed et al. (2016), rotational manipulation using acoustic waves','relevance':'Experiment reports microbubble-driven microstreaming and rotation at kHz; scale/frequency differ from current 2.5 MHz.'},{'url':'https://docs.fenicsproject.org/dolfinx/main/python/demos/demo_stokes.html','title':'DOLFINx official Taylor-Hood Stokes demo','relevance':'Mature incompressible solver; no device-specific acoustic forcing or boundary calibration supplied.'},{'url':'https://github.com/polycfd/apecss','title':'APECSS upstream software','relevance':'Supports response generation; any new bubble class requires matching validated inputs.'}],identity=identity())
 field=BASE/'FIELD_3D_2500000.h5'
 if field.exists():
  import h5py
  with h5py.File(field) as h:
   x=h['yz_center/positions_m'][:];F=h['yz_center/force_N'][:];j=int(np.argmin(np.linalg.norm(x-[0,0,60e-6],axis=1)))
  out['buoyancy_to_restoring_Fz_diagnostic']=dict(position_m=x[j],acoustic_Fz_N=F[j,2],buoyancy_upper_force_N=Fb,absolute_force_ratio=Fb/max(abs(F[j,2]),1e-99),scope='Force-scale comparison only. Gravity orientation, shell mass and actual field remain uncalibrated; no equilibrium/trajectory predicted.')
 write(BASE/'MISSING_PHYSICS_PREFLIGHT.json',out)
if __name__=='__main__':main()
